searchUrl:
@js:// 获取源代码中的Token拼接到搜索地址
var html = java.ajax(source.key);
var token = html.match(/name="_token" value="(.+?)"/);  
token = token ? token[1] : null;

var body = `_token=${token}&keyword=${key}&action=login`;
var option = { 
  "charset": "utf-8",
  "method": "POST",
  "body": body
};
source.key + "/search," + JSON.stringify(option);

