ruleContent.content:
#chapter@html@js:
var html = result;
// 砍掉推荐阅读区域（稳定class）
var t = html.indexOf('class=\"tjlm\"');
if (t > -1) {
  var d = html.indexOf('</div>', t);
  if (d > -1) html = html.substring(0, t - 6) + html.substring(d + 6);
}
// 砍掉书籍信息区 rdinfo（书名/作者/字数/时间，稳定class）
var r = html.indexOf('class=\"rdinfo\"');
if (r > -1) {
  var rd = html.indexOf('</div>', r);
  if (rd > -1) html = html.substring(0, r - 6) + html.substring(rd + 6);
}
// 砍掉所有上下导航 ydgong（稳定class）
while (true) {
  var y = html.indexOf('class=\"ydgong\"');
  if (y === -1) break;
  var yd = html.indexOf('</div>', y);
  if (yd === -1) break;
  html = html.substring(0, y - 6) + html.substring(yd + 6);
}
// 砍掉所有来源行（class 含 hid/shid/shidp，支持 div/p/article 标签）
while (true) {
  var sh = html.indexOf('class=\"hid\"');
  if (sh === -1) sh = html.indexOf('class=\"shid\"');
  if (sh === -1) sh = html.indexOf('class=\"shidp\"');
  if (sh === -1) break;
  var ts = html.lastIndexOf('<', sh);
  var cd = html.indexOf('</div>', sh);
  var cp = html.indexOf('</p>', sh);
  var ca = html.indexOf('</article>', sh);
  var ce = -1, clen = 0;
  if (cd > -1) { ce = cd; clen = 6; }
  if (cp > -1 && (ce === -1 || cp < ce)) { ce = cp; clen = 4; }
  if (ca > -1 && (ce === -1 || ca < ce)) { ce = ca; clen = 10; }
  if (ce === -1 || ts === -1) break;
  html = html.substring(0, ts) + html.substring(ce + clen);
}
// 砍掉章节标题 h2
var h2s = html.indexOf('<h2');
if (h2s > -1) {
  var h2e = html.indexOf('</h2>', h2s);
  if (h2e > -1) html = html.substring(0, h2s) + html.substring(h2e + 5);
}
// </p> → 换行、<br> → 换行
html = html.split('</p>').join('\
');
html = html.split('<br/>').join('\
');
html = html.split('<br>').join('\
');
// 手动去HTML标签
var out = '';
var inTag = false;
for (var ci = 0; ci < html.length; ci++) {
  var ch = html.charAt(ci);
  if (ch === '<') { inTag = true; continue; }
  if (ch === '>') { inTag = false; continue; }
  if (!inTag) out += ch;
}
// 行过滤：去掉残留杂质（来源/导航/元数据）
var lines = out.split('\
');
var clean = [];
for (var li = 0; li < lines.length; li++) {
  var l = lines[li];
  var low = l.toLowerCase();
  if (low.indexOf('pinshuzhai') > -1) continue;
  if (l.indexOf('品书斋') > -1) continue;
  if (l.indexOf('章节列表') > -1) continue;
  if (l.indexOf('下一章') > -1) continue;
  if (l.indexOf('上一章') > -1) continue;
  if (l.indexOf('推荐阅读') > -1) continue;
  if (l.match(/\\d+字/) || l.match(/\\d{4}-\\d{2}-\\d{2}/)) continue;
  var trimmed = l.replace(/\\u3000/g, '').replace(/ /g, '');
  if (!trimmed || trimmed === '→') continue;
  clean.push(l);
}
result = clean.join('\
');

